{
  "openapi": "3.1.0",
  "info": {
    "title": "dashboard",
    "version": "1.0.0"
  },
  "paths": {
    "/": {
      "get": {
        "operationId": "dashboard_get_",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "text/html": {
                "schema": {
                  "type": "string"
                }
              }
            }
          },
          "500": {
            "description": "500",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          }
        }
      }
    },
    "/api/weather": {
      "get": {
        "operationId": "dashboard_get_api_weather",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "required": [
                      "id",
                      "name",
                      "latitude",
                      "longitude",
                      "forecast"
                    ],
                    "properties": {
                      "id": {
                        "type": "string",
                        "enum": [
                          "oslo",
                          "helsinki",
                          "lisbon"
                        ]
                      },
                      "name": {
                        "type": "string"
                      },
                      "latitude": {
                        "type": "number",
                        "minimum": -90,
                        "maximum": 90
                      },
                      "longitude": {
                        "type": "number",
                        "minimum": -180,
                        "maximum": 180
                      },
                      "forecast": {
                        "oneOf": [
                          {
                            "type": "object",
                            "required": [
                              "updatedAt",
                              "fetchedAt",
                              "mode",
                              "periods"
                            ],
                            "properties": {
                              "updatedAt": {
                                "type": "string",
                                "format": "date-time"
                              },
                              "fetchedAt": {
                                "type": "string",
                                "format": "date-time"
                              },
                              "mode": {
                                "type": "string",
                                "enum": [
                                  "fixture",
                                  "live"
                                ]
                              },
                              "periods": {
                                "type": "array",
                                "minItems": 1,
                                "maxItems": 6,
                                "items": {
                                  "type": "object",
                                  "required": [
                                    "time",
                                    "temperatureC",
                                    "precipitationMm",
                                    "symbol"
                                  ],
                                  "properties": {
                                    "time": {
                                      "type": "string",
                                      "format": "date-time"
                                    },
                                    "temperatureC": {
                                      "type": "number"
                                    },
                                    "precipitationMm": {
                                      "type": [
                                        "number",
                                        "null"
                                      ],
                                      "minimum": 0
                                    },
                                    "symbol": {
                                      "type": "string"
                                    }
                                  }
                                }
                              }
                            }
                          },
                          {
                            "type": "null"
                          }
                        ]
                      }
                    }
                  }
                }
              }
            }
          },
          "500": {
            "description": "500",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          }
        }
      }
    },
    "/api/places": {
      "post": {
        "operationId": "dashboard_post_api_places",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "id",
                    "name",
                    "latitude",
                    "longitude"
                  ],
                  "properties": {
                    "id": {
                      "type": "string",
                      "enum": [
                        "oslo",
                        "helsinki",
                        "lisbon"
                      ]
                    },
                    "name": {
                      "type": "string"
                    },
                    "latitude": {
                      "type": "number",
                      "minimum": -90,
                      "maximum": 90
                    },
                    "longitude": {
                      "type": "number",
                      "minimum": -180,
                      "maximum": 180
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "400",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          },
          "415": {
            "description": "415"
          },
          "500": {
            "description": "500",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          },
          "503": {
            "description": "503",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          }
        },
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "required": [
                  "cityId"
                ],
                "additionalProperties": false,
                "properties": {
                  "cityId": {
                    "type": "string",
                    "enum": [
                      "oslo",
                      "helsinki",
                      "lisbon"
                    ]
                  }
                }
              }
            }
          }
        }
      }
    },
    "/api/places/{id}/refresh": {
      "post": {
        "operationId": "dashboard_post_api_places_id_refresh",
        "responses": {
          "202": {
            "description": "202",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "required": [
                    "placeId",
                    "status"
                  ],
                  "properties": {
                    "placeId": {
                      "type": "string"
                    },
                    "status": {
                      "const": "QUEUED"
                    }
                  }
                }
              }
            }
          },
          "404": {
            "description": "404",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          },
          "500": {
            "description": "500",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          },
          "503": {
            "description": "503",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          }
        },
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string",
              "enum": [
                "oslo",
                "helsinki",
                "lisbon"
              ]
            }
          }
        ]
      }
    },
    "/health": {
      "get": {
        "operationId": "dashboard_get_health",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "database": {
                      "const": "READY"
                    },
                    "kafka": {
                      "const": "READY"
                    }
                  }
                }
              }
            }
          },
          "500": {
            "description": "500",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          }
        }
      }
    },
    "/openapi.json": {
      "get": {
        "operationId": "dashboard_get_openapi.json",
        "responses": {
          "200": {
            "description": "200",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "additionalProperties": true
                }
              }
            }
          },
          "500": {
            "description": "500",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  },
                  "additionalProperties": true
                }
              }
            }
          }
        }
      }
    }
  }
}
